/** 분당 70m 보행 속도로 왕복 이동·대기·식사 시간을 합산합니다. */
export function totalMinutes(menu) {
  return Math.ceil(menu.distance / 70) * 2 + menu.meal + menu.wait;
}

const asList = value => value instanceof Set ? [...value] : Array.isArray(value) ? value : typeof value === 'string' ? [value] : [];
const upperLimit = value => value === undefined || value === null || value === '' || !Number.isFinite(Number(value)) ? Infinity : Math.max(0, Number(value));

export const LOCATIONS={'독산역':[37.4666,126.8895],'금천구청':[37.4569,126.8955],'금천구청역':[37.4556,126.8939],'가산디지털단지역':[37.4811,126.8826]};
export function distanceMeters(lat,lng,origin){const rad=v=>v*Math.PI/180;const a=rad(lat-origin[0]),b=rad(lng-origin[1]);return Math.round(6371000*2*Math.asin(Math.min(1,Math.sqrt(Math.sin(a/2)**2+Math.cos(rad(lat))*Math.cos(rad(origin[0]))*Math.sin(b/2)**2))));}
export function filterMenus({budget,time,distance,categories,blacklist,location='독산역'}={}){
 const origin=LOCATIONS[location]||LOCATIONS['독산역'],selected=asList(categories),excluded=new Set(asList(blacklist));
 return MENUS.filter(m=>(!selected.length||selected.includes('전체')||selected.includes(m.category))&&!excluded.has(m.id)&&!excluded.has(m.name)).map(m=>{
 const offers=m.offers.map(o=>({...o,distance:distanceMeters(o.lat,o.lng,origin)})).filter(o=>o.price<=upperLimit(budget)&&o.distance<=upperLimit(distance)&&Math.ceil(o.distance/70)*2+m.meal+m.wait<=upperLimit(time)).sort((a,b)=>a.distance-b.distance);
 return offers.length?{...m,offers,price:offers[0].price,distance:offers[0].distance}:null;
 }).filter(Boolean);
}

/** 나머지 연산 편향을 피하기 위해 범위를 벗어난 난수는 다시 받습니다. */
export function randomIndex(n) {
  const range = 2 ** 32;
  if (!Number.isSafeInteger(n) || n < 1 || n > range) {
    throw new RangeError('후보 수는 1 이상 2³² 이하의 정수여야 합니다.');
  }
  if (n === 1) return 0;
  if (!globalThis.crypto?.getRandomValues) throw new Error('안전한 난수를 사용할 수 없는 환경입니다.');
  const acceptedRange = Math.floor(range / n) * n;
  const sample = new Uint32Array(1);
  do {
    globalThis.crypto.getRandomValues(sample);
  } while (sample[0] >= acceptedRange);
  return sample[0] % n;
}

export function pickMenu(candidates, avoidId) {
  if (!Array.isArray(candidates)) throw new TypeError('메뉴 후보는 배열이어야 합니다.');
  if (!candidates.length) return null;
  const otherMenus = candidates.filter(menu => menu.id !== avoidId);
  const pool = otherMenus.length ? otherMenus : candidates;
  return pool[randomIndex(pool.length)];
}

/**
 * 이미 결정된 당첨 위치까지 순차 강조하는 연출 계획입니다. 난수는 사용하지 않습니다.
 * 각 항목의 delayMs 동안 index를 표시하면 전체 연출 시간이 durationMs가 됩니다.
 */
export function createSpotlightPlan(count, target, durationMs = 5000) {
  if (!Number.isSafeInteger(count) || count < 1) {
    throw new RangeError('후보 수는 1 이상의 안전한 정수여야 합니다.');
  }
  if (!Number.isSafeInteger(target) || target < 0 || target >= count) {
    throw new RangeError('당첨 위치는 후보 범위 안의 정수여야 합니다.');
  }
  // 0에서 출발해 세 바퀴를 완주한 다음 당첨 위치까지 순서대로 진행합니다.
  const steps = count * 3 + target + 1;
  if (!Number.isSafeInteger(steps) || !Number.isSafeInteger(durationMs) || durationMs < steps) {
    throw new RangeError('연출 시간은 각 강조 단계에 최소 1ms를 배정할 수 있는 정수여야 합니다.');
  }
  const weights = Array.from({ length: steps }, (_, index) => 1 + 7 * (index / (steps - 1)) ** 3);
  const weightSum = weights.reduce((sum, weight) => sum + weight, 0);
  const remainingMs = durationMs - steps;
  const plan = weights.map((weight, index) => ({
    index: index % count,
    delayMs: 1 + Math.floor(remainingMs * weight / weightSum),
  }));
  // 내림으로 남은 정수 ms는 뒤쪽부터 보충해 총시간과 비감소 지연을 함께 지킵니다.
  const remainder = durationMs - plan.reduce((sum, step) => sum + step.delayMs, 0);
  for (let index = steps - remainder; index < steps; index++) plan[index].delayMs++;
  return plan;
}

const amountPattern = /(?:(?:\d[\d,]*(?:\.\d+)?\s*)?만\s*)?(?:(?:\d[\d,]*(?:\.\d+)?\s*)?천\s*)?(?:\d[\d,]*(?:\.\d+)?\s*)?원/g;

function parseWon(value) {
  let rest = value.replace(/[\s,원]/g, '');
  if (!rest) return null;
  let amount = 0;
  rest = rest.replace(/(\d+(?:\.\d+)?)?만/, (_, digits) => {
    amount += Number(digits || 1) * 10000;
    return '';
  });
  rest = rest.replace(/(\d+(?:\.\d+)?)?천/, (_, digits) => {
    amount += Number(digits || 1) * 1000;
    return '';
  });
  if (rest) amount += Number(rest);
  return Number.isFinite(amount) && amount >= 0 ? Math.round(amount) : null;
}

/** 외부 AI 호출 없이, 문장에 명시한 조건만 읽는 한국어 데모 파서입니다. */
export function parsePrompt(text, baseFilters = {}) {
  const filters = { ...baseFilters };
  if (baseFilters.categories !== undefined) filters.categories = [...asList(baseFilters.categories)];
  if (baseFilters.blacklist !== undefined) filters.blacklist = [...asList(baseFilters.blacklist)];
  const notes = [];
  const source = String(text ?? '').normalize('NFKC');
  const amounts = [...source.matchAll(amountPattern)].map(match => parseWon(match[0])).filter(value => value !== null);
  if (amounts.length) {
    filters.budget = amounts.at(-1);
    notes.push(`한 끼 예산 ${filters.budget.toLocaleString('ko-KR')}원 이하`);
  }

  const walking = [...source.matchAll(/(?:(왕복)\s*)?(?:도보(?:로)?|걸어서|걸어(?:서)?\s*편도)\s*(?:편도\s*)?(\d+(?:\.\d+)?)\s*분/g)];
  if (walking.length) {
    const match = walking.at(-1);
    filters.distance = Math.round(Number(match[2]) * 70 / (match[1] ? 2 : 1));
    notes.push(`${match[1] ? '왕복 ' : '편도 '}도보 ${match[2]}분 → 편도 ${filters.distance}m`);
  }
  const timeMatches = [...source.matchAll(/(\d+(?:\.\d+)?)\s*분/g)].filter(match =>
    !walking.some(walk => match.index >= walk.index && match.index < walk.index + walk[0].length)
  );
  if (timeMatches.length) {
    filters.time = Math.round(Number(timeMatches.at(-1)[1]));
    notes.push(`왕복 이동·대기·식사 총 ${filters.time}분 이내`);
  }

  const distances = [...source.matchAll(/(\d[\d,]*(?:\.\d+)?)\s*(km|킬로미터|킬로|m|미터)(?![a-z])/gi)];
  if (distances.length) {
    const match = distances.at(-1);
    const scale = /^(km|킬로미터|킬로)$/i.test(match[2]) ? 1000 : 1;
    filters.distance = Math.round(Number(match[1].replaceAll(',', '')) * scale);
    notes.push(`편도 거리 ${filters.distance}m 이내`);
  }

  const requestedCategories = [];
  const excludedCategories = [];
  for (const category of CATEGORIES) {
    const pattern = new RegExp(`${category}(?:은|는|을|를)?\\s*(말고|빼고|제외)`);
    if (pattern.test(source)) excludedCategories.push(category);
    else if (source.includes(category)) requestedCategories.push(category);
  }
  if (requestedCategories.length) {
    filters.categories = requestedCategories;
    notes.push(`음식 종류: ${requestedCategories.join(' · ')}`);
  } else if (excludedCategories.length) {
    filters.categories = CATEGORIES.filter(category => !excludedCategories.includes(category));
    notes.push(`${excludedCategories.join(' · ')} 제외`);
  } else if (/아무거나|종류\s*(?:무관|상관없)|음식\s*종류\s*전체/.test(source)) {
    filters.categories = [];
    notes.push('음식 종류 전체');
  }

  const excludedMenus = MENUS.filter(menu => new RegExp(`${menu.name.replace(/[.*+?^${}()|[\]\\]/g, '\\$&')}(?:은|는|을|를)?\\s*(?:말고|빼고|제외)`).test(source));
  if (excludedMenus.length) {
    filters.blacklist = [...new Set([...asList(filters.blacklist), ...excludedMenus.map(menu => menu.id)])];
    notes.push(`${excludedMenus.map(menu => menu.name).join(' · ')} 제외`);
  }
  return { filters, notes };
}

/** rung의 row는 1..rows, col은 두 세로선 중 왼쪽 선의 번호입니다. */
export function buildLadder(count, rows = 10) {
  if (!Number.isInteger(count) || count < 2 || count > 8) throw new RangeError('사다리는 2~8명이 참여할 수 있습니다.');
  if (!Number.isInteger(rows) || rows < 1 || rows > 100) throw new RangeError('사다리 높이는 1~100행이어야 합니다.');
  const rungs = [];
  for (let row = 1; row <= rows; row++) {
    for (let col = 0; col < count - 1; col++) {
      if (randomIndex(2) === 1) {
        rungs.push({ row, col });
        col++;
      }
    }
  }
  if (!rungs.length) rungs.push({ row: randomIndex(rows) + 1, col: randomIndex(count - 1) });

  return {
    count,
    rows,
    rungs,
    trace(start) {
      if (!Number.isInteger(start) || start < 0 || start >= count) throw new RangeError('출발점이 사다리 범위를 벗어났습니다.');
      let x = start;
      const points = [{ x, y: 0 }];
      for (let row = 1; row <= rows; row++) {
        points.push({ x, y: row });
        const rung = rungs.find(item => item.row === row && (item.col === x || item.col + 1 === x));
        if (rung) {
          x = rung.col === x ? x + 1 : x - 1;
          points.push({ x, y: row });
        }
      }
      points.push({ x, y: rows + 1 });
      return { end: x, points };
    },
  };
}
